from fastapi import FastAPI, File, Form, UploadFile
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.post("/upload1")
async def upload1(form_data: str = Form(...), file: UploadFile = File(...)):
    return {"form_data": form_data, "file": file.filename}

@app.post("/upload2")
async def upload2(file: UploadFile = File(...), form_data: str = Form(...)):
    return {"form_data": form_data, "file": file.filename}

@app.post("/upload3")
async def upload3(form_data: str = Form(...), file1: UploadFile = File(...), file2: UploadFile = File(...)):
    return {"form_data": form_data, "file1": file1.filename, "file2": file2.filename}

client = TestClient(app)

def test_form_before_file():
    response = client.post(
        "/upload1",
        data={"form_data": "test value"},
        files={"file": ("test.txt", b"test content")}
    )
    print(f"upload1 status: {response.status_code}")
    assert response.status_code == 200

def test_file_before_form():
    response = client.post(
        "/upload2",
        data={"form_data": "test value"},
        files={"file": ("test.txt", b"test content")}
    )
    print(f"upload2 status: {response.status_code}")
    assert response.status_code == 200

def test_form_before_multiple_files():
    response = client.post(
        "/upload3",
        data={"form_data": "test value"},
        files={"file1": ("test1.txt", b"content1"), "file2": ("test2.txt", b"content2")}
    )
    print(f"upload3 status: {response.status_code}")
    assert response.status_code == 200

if __name__ == "__main__":
    try:
        test_form_before_file()
        test_file_before_form()
        test_form_before_multiple_files()
        print("All tests passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import sys
        sys.exit(1)

