from fastapi import FastAPI, File, Form
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.post("/mixed")
async def mixed_endpoint(form_data: str = Form(...), file_data: bytes = File(...)):
    return {"form_data": form_data, "file_data": file_data}

client = TestClient(app)

def test_mixed_form_file():
    # File after Form
    response = client.post(
        "/mixed",
        data={"form_data": "hello"},
        files={"file_data": b"world"}
    )
    assert response.status_code == 200
    assert response.json() == {"form_data": "hello", "file_data": b"world"}

if __name__ == "__main__":
    test_mixed_form_file()

